61.   constructor(config: CartConfig = {}) {
62.     this.discountPolicy = config.discountPolicy ?? new NoDiscountPolicy();
63.     this.taxCalculator = config.taxCalculator ?? new NoTaxCalculator();
64.     this.shippingCalculator =
65.       config.shippingCalculator ?? new FreeShippingCalculator();
66.     this.region = config.region ?? "US";
67.   }
68. 
69.   add(product: Product, quantity: number): void {
70.     if (!Number.isInteger(quantity) || quantity <= 0) {
71.       throw new RangeError(`quantity must be a positive integer (got ${quantity})`);
72.     }
73.     if (product.unitPriceCents < 0) {
74.       throw new RangeError(`unitPriceCents must be non-negative (got ${product.unitPriceCents})`);
75.     }
76. 
77.     const existing = this.lines.get(product.id);
78.     if (existing) {
79.       existing.quantity += quantity;
80.     } else {
81.       this.lines.set(product.id, { product, quantity });
82.     }
83.   }
84. 
