        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
      { upToGrams: 5000, costCents: 1200 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const lines = [makeLine("a", undefined, 3)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects first bracket when weight <= first upToGrams", () => {
      const lines = [makeLine("a", 250, 2)]; // 500g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects second bracket for weight just above first boundary", () => {
      const lines = [makeLine("a", 501, 1)]; // 501g
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects bracket at exact boundary", () => {
      const lines = [makeLine("a", 2000, 1)]; // 2000g exactly
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 2000, costCents: 700 },
        ],
        1500,
      );
      const lines = [makeLine("a", 3000, 1)]; // 3000g
      expect(calcWithOverflow.computeShippingCents(lines, 1000)).toBe(1500);
    });

    it("defaults overflow to heaviest bracket cost", () => {
      const lines = [makeLine("a", 6000, 1)]; // 6000g > 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      const lines = [makeLine("a", 400, 1)]; // 400g → first bracket
      expect(unsorted.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

