        computeShippingCents: () => 200,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(productA, 1); // subtotal=1000
      const totals = cart.totals();
      // discounted = 900, tax = 50, shipping = 200
      expect(totals.totalCents).toBe(900 + 50 + 200);
    });

    it("empty cart has all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
